-- Темы 18–20: исправлены странности в 31 вопросе (58 исправлений), прежние версии в question_archive (миграция 119), ключи не меняются.
-- Источник: scripts/questions/120_oddities_topics18_20.js
-- Повторный запуск безопасен: вопрос и вариант ищутся по тексту, прежнее или уже новое значение допустимо,
-- иначе пакет отменяется. Ключи ответов, число и порядок вариантов не меняются.

BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

DO $fix$
DECLARE fix record; matches integer; qid integer; k text;
BEGIN
    FOR fix IN SELECT * FROM (VALUES
        ('question', 'В /proc/PID/maps главного процесса PostgreSQL есть такие области. Какая из них разделяемая, то есть общая для процессов сервера?', NULL, NULL, NULL, 'В /proc/PID/maps главного процесса PostgreSQL есть приведённые области. Какое отображение допускает общую запись нескольких процессов?'),
        ('question', 'Допишите команду psql, чтобы передать оболочке номер серверного процесса, обслуживающего это подключение. Номер перед этим сохранён командой SELECT pg_backend_pid() AS pid \gset:
```
\___ MYPID :pid
\! grep VmRSS /proc/$MYPID/status
```', NULL, NULL, NULL, 'psql работает на том же сервере Linux и в том же пространстве PID, что и PostgreSQL; status процесса доступен для чтения. Допишите команду, передающую оболочке PID серверного процесса. Он уже сохранён командой SELECT pg_backend_pid() AS pid \gset:
```
\___ MYPID :pid
\! grep VmRSS /proc/$MYPID/status
```'),
        ('question', 'Процесс не использует HugeTLB. У него VmSize равен 439 МБ, VmRSS — 15 МБ, VmSwap — 1 МБ. Что из этого верно?', NULL, NULL, NULL, 'Процесс не использует HugeTLB. VmSize = 439 МБ, VmRSS = 15 МБ, VmSwap = 1 МБ. Какова сумма его резидентной памяти и приватной памяти, учтённой в свопе?'),
        ('question', 'Зачем ядру нужно регулярное прерывание от таймера?', NULL, NULL, NULL, 'Зачем ядру таймерные прерывания при вытесняющем планировании задач?'),
        ('question', 'Что напечатает этот фрагмент?
```
ssize_t n = write(-1, "x", 1);
int saved = errno;
printf("%zd %s\n", n, strerror(saved));
```', NULL, NULL, NULL, 'Что напечатает этот фрагмент в Linux x86-64 с glibc и локалью сообщений C?
```
ssize_t n = write(-1, "x", 1);
int saved = errno;
printf("%zd %s\n", n, strerror(saved));
```'),
        ('question', 'Допишите последнюю команду, чтобы посмотреть фактический план удаления, но не удалить строки:
```
BEGIN;
EXPLAIN ANALYZE DELETE FROM t WHERE id <= 10;
___;
```', NULL, NULL, NULL, 'Допишите последнюю команду, чтобы получить фактический план DELETE и отменить его транзакционные изменения:
```
BEGIN;
EXPLAIN ANALYZE DELETE FROM t WHERE id <= 10;
___;
```'),
        ('question', 'У таблицы t 637 страниц и 100 000 строк, параметры стоимости по умолчанию. Какой будет полная стоимость узла Seq Scan для этого запроса?
```
EXPLAIN SELECT * FROM t WHERE id > 10;
```', NULL, NULL, NULL, 'Планировщик оценивает обычную таблицу t в 637 страниц и 100 000 строк, id имеет тип integer. Параметры стоимости стандартные. Какова полная стоимость непараллельного Seq Scan для запроса?
```
EXPLAIN SELECT * FROM t WHERE id > 10;
```'),
        ('question', 'Внутренний узел Nested Loop в EXPLAIN ANALYZE выглядит так. Сколько строк он вернул всего и сколько времени занял в сумме?
```
Index Scan using t_pkey on t (actual time=0.010..0.012 rows=1 loops=500)
```', NULL, NULL, NULL, 'Во внутренней ветке Nested Loop показан такой Index Scan. Сколько строк он вернул всего и сколько времени суммарно провёл в работе?
```
Index Scan using t_pkey on t (actual time=0.010..0.012 rows=1 loops=500)
```'),
        ('question', 'После загрузки большой таблицы ANALYZE вручную не выполняли. При каком объёме изменений таблица станет кандидатом на автоматический ANALYZE при настройках по умолчанию?', NULL, NULL, NULL, 'Таблица уже проходила ANALYZE; оценка числа строк в pg_class.reltuples актуальна и положительна. При каком объёме изменений с последнего анализа она станет кандидатом на автоматический ANALYZE при настройках по умолчанию?'),
        ('option', 'Что такое виртуальная память процесса?', 'Память видеокарты, которую система использует как расширение оперативной памяти', NULL, 'К виртуальной памяти процесса память видеокарты отношения не имеет.', 'Виртуальная память определяется адресным пространством процесса, а не использованием видеопамяти вместо RAM.'),
        ('option', 'Что обычно хранится в стеке процесса?', 'Локальные переменные выполняемых в данный момент функций', NULL, 'Они лежат в кадре функции и исчезают при выходе из неё.', 'Локальные переменные могут храниться в кадре функции или в регистрах; их время жизни заканчивается при выходе из соответствующей области.'),
        ('explanation', 'Что обычно хранится в стеке процесса?', NULL, NULL, 'При каждом вызове функции в стеке создаётся кадр: её локальные переменные, сохранённые значения регистров и адрес возврата. При выходе из функции кадр снимается.', 'Обычно стек хранит адреса возврата, сохранённые регистры и часть локальных переменных. Точное размещение зависит от архитектуры и оптимизации.'),
        ('option', 'Что не так в этой функции?
```
int *make(void)
{
    int x = 42;
    return &x;
}
```', 'Возвращается адрес локальной переменной, чей кадр уже снят со стека', NULL, 'После выхода из функции её кадр в стеке освобождён, указатель становится «висячим»: эту память перезапишет следующий вызов функции.', 'Время жизни x заканчивается при возврате из make. Возвращённый указатель нельзя разыменовывать: это неопределённое поведение, независимо от сохранности старых байтов.'),
        ('option', 'Что не так в этой функции?
```
int *make(void)
{
    int x = 42;
    return &x;
}
```', 'Такой код не скомпилируется, потому что возвращается адрес переменной', NULL, 'Код компилируется, обычно с предупреждением; ошибка проявится во время выполнения.', 'Компилятор обычно принимает такой код с предупреждением; конкретное проявление неопределённого поведения не гарантировано.'),
        ('explanation', 'Допишите код, чтобы вернуть память, выделенную через malloc:
```
char *buf = malloc(1024);
/* ... работа с buf ... */
___(buf);
```', NULL, NULL, 'Каждому успешному malloc должен соответствовать ровно один free. Если забыть free, будет утечка памяти; если вызвать дважды — неопределённое поведение.', 'В этом фрагменте ненужный блок malloc освобождают вызовом free один раз. Повторное освобождение — неопределённое поведение; выход из функции сам блок не освобождает.'),
        ('option', 'Какие утверждения о стеке и куче верны?', 'Блок из кучи существует, пока его не освободят вызовом free', 'Выход из функции сам по себе не освобождает блок malloc', 'Время жизни блока в куче определяет программа.', 'Динамическую память освобождают явно, например через free или при перераспределении realloc; ресурсы завершившегося процесса возвращает ОС.'),
        ('explanation', 'Какие утверждения о стеке и куче верны?', NULL, NULL, 'Главное различие — время жизни: стек живёт вместе с вызовом функции, куча — пока программа сама не освободит память.', 'Снятие кадра стека связано с выходом из функции; время жизни динамического выделения от этого выхода не зависит.'),
        ('option', 'Что верно для механизма OOM killer в Linux? PostgreSQL работает с restart_after_crash по умолчанию, postmaster продолжает работать.', 'При нехватке памяти OOM killer перезагружает сервер, чтобы очистить всю оперативную память', NULL, 'Он завершает отдельный процесс, а не весь сервер.', 'OOM killer завершает выбранные процессы, а не перезагружает ОС. При memory.oom.group = 1 могут совместно завершаться процессы группы.'),
        ('explanation', 'Что верно для приватных страниц памяти дочернего процесса, созданного вызовом fork() в Linux, если общая память явно не подключалась?', NULL, NULL, 'Поэтому fork быстрый даже у процесса с большой памятью. PostgreSQL в Linux порождает обслуживающие процессы через fork от postmaster: они сразу получают загруженный код и настройки.', 'fork не копирует сразу содержимое всех приватных страниц, но создаёт структуры процесса и копирует таблицы страниц. Стоимость зависит от отображений родителя; PostgreSQL наследует код и настройки postmaster.'),
        ('option', 'В чём главное отличие стека от кучи?', 'Память стека освобождается при выходе из функции, а блок кучи — когда программа вернёт его', NULL, 'Стек живёт вместе с вызовом функции, куча — пока программа не вызовет free.', 'Выход из функции убирает её кадр, но не выделенные через malloc блоки. Освобождением блоков управляет программа, а ресурсы завершившегося процесса возвращает ОС.'),
        ('explanation', 'В чём главное отличие стека от кучи?', NULL, NULL, 'Стек быстрый и управляется автоматически, но невелик (обычно 8 МБ) и хранит данные только на время вызова функции. Куча больше и гибче, но за освобождение памяти отвечает программа: забытый free приводит к утечке.', 'Лимиты и фактические размеры стека и кучи зависят от процесса и настроек. Кадр функции снимается автоматически; динамические блоки от выхода из функции не освобождаются.'),
        ('option', 'В /proc/PID/maps файл locale-archive занимает около 232 МБ адресов, а процесс занимает в оперативной памяти всего несколько мегабайт. Как это возможно?', 'В оперативной памяти находится небольшая часть отображённого файла', 'Резидентной в этом процессе стала малая часть отображения', 'Отображение файла не требует загрузки всех его страниц: размер области в maps — это объём зарезервированных виртуальных адресов, а не занятой оперативной памяти, и резидентной может быть малая часть.', 'Размер отображения не равен RSS этого процесса: резидентной в нём может быть малая часть. Другие страницы файла при этом могут находиться в общем кеше ОС.'),
        ('option', 'В /proc/PID/maps главного процесса PostgreSQL есть приведённые области. Какое отображение допускает общую запись нескольких процессов?', '7f58aa3f3000-7f58aa549000 r-xp 00026000 fe:01 1478 /usr/lib/x86_64-linux-gnu/libc.so.6', NULL, 'Это код библиотеки (r-xp): только чтение и выполнение, область приватная.', 'Отображение кода приватное и недоступно для записи; неизменённые физические страницы libc могут совместно использоваться процессами.'),
        ('explanation', 'В /proc/PID/maps главного процесса PostgreSQL есть приведённые области. Какое отображение допускает общую запись нескольких процессов?', NULL, NULL, 'Права rw-s обозначают разделяемую область с чтением и записью. Основная общая область PostgreSQL создаётся при запуске сервера и содержит shared_buffers и другие общие структуры, но одного признака rw-s мало, чтобы определить назначение области: таких областей у сервера может быть несколько. Приватные области (последняя буква p) у каждого процесса свои. Общие области главного процесса: grep rw-s /proc/PID/maps (PID — первая строка postmaster.pid).', 's обозначает разделяемое отображение, p — приватное с копированием при записи. Буква p не означает, что все физические страницы уже принадлежат исключительно одному процессу. Основная общая область PostgreSQL создаётся при запуске сервера и содержит shared_buffers и другие общие структуры; таких областей у сервера может быть несколько. Общие области главного процесса: grep rw-s /proc/PID/maps (PID — первая строка postmaster.pid).'),
        ('option', 'Что показывает поле VmSize в /proc/PID/status?', 'Размер виртуального адресного пространства процесса, включая адреса без памяти', 'Суммарный размер отображённых виртуальных областей процесса', 'Сюда входят код, данные, куча, стек, библиотеки и отображённые файлы: все зарезервированные адреса, в том числе ещё не занятые оперативной памятью.', 'Суммируются размеры виртуальных отображений, даже если физические страницы ещё не выделены. Неотображённые промежутки между областями в VmSize не входят.'),
        ('option', 'Процесс не использует HugeTLB. VmSize = 439 МБ, VmRSS = 15 МБ, VmSwap = 1 МБ. Какова сумма его резидентной памяти и приватной памяти, учтённой в свопе?', 'VmSize — 439 МБ, RSS — около 15 МБ, приватные страницы в свопе — около 1 МБ', 'Около 16 МБ', 'VmSize — зарезервированные адреса, VmRSS — страницы в оперативной памяти (оценка), VmSwap — приватные анонимные страницы в свопе; своп разделяемой памяти сюда не входит.', '15 МБ RSS + 1 МБ приватной памяти в свопе. Это сумма показателей, а не уникальная доля процесса в RAM.'),
        ('option', 'Процесс не использует HugeTLB. VmSize = 439 МБ, VmRSS = 15 МБ, VmSwap = 1 МБ. Какова сумма его резидентной памяти и приватной памяти, учтённой в свопе?', 'VmSize — 439 МБ, RSS — около 1 МБ, приватные страницы в свопе — около 15 МБ', 'Около 439 МБ', 'Значения перепутаны: VmRSS показывает около 15 МБ в оперативной памяти, а VmSwap — около 1 МБ приватных анонимных страниц в свопе, без свопа разделяемой памяти.', '439 МБ — виртуальный размер VmSize, а не резидентная память.'),
        ('option', 'Процесс не использует HugeTLB. VmSize = 439 МБ, VmRSS = 15 МБ, VmSwap = 1 МБ. Какова сумма его резидентной памяти и приватной памяти, учтённой в свопе?', 'VmSize — 16 МБ, RSS — около 15 МБ, приватные страницы в свопе — около 1 МБ', 'Около 455 МБ', 'Виртуальное адресное пространство — это VmSize, 439 МБ: в него входят и зарезервированные адреса, а не только сумма RSS и свопа.', 'VmSize нельзя прибавлять к RSS и VmSwap: это другой показатель.'),
        ('option', 'Процесс не использует HugeTLB. VmSize = 439 МБ, VmRSS = 15 МБ, VmSwap = 1 МБ. Какова сумма его резидентной памяти и приватной памяти, учтённой в свопе?', 'VmSize — 439 МБ, RSS — около 439 МБ, приватные страницы в свопе — около 1 МБ', 'Около 440 МБ', 'Столько адресов зарезервировано; в оперативной памяти находятся около 15 МБ.', 'VmSize + VmSwap не даёт требуемую сумму.'),
        ('option', 'Какое поле /proc/meminfo показывает, сколько памяти можно выделить новым программам без вытеснения в своп?', '`MemFree`', NULL, 'Это совсем незанятая память; часть кеша тоже можно освободить, поэтому доступно больше.', 'MemFree — совсем свободные страницы. MemAvailable учитывает также освобождаемую память и резерв ядра, поэтому не обязан быть больше MemFree.'),
        ('option', 'Зачем ядру таймерные прерывания при вытесняющем планировании задач?', 'Чтобы регулярно получать управление над процессором', 'Чтобы вытеснять задачи и обрабатывать таймеры', 'Так работает вытесняющая многозадачность: ядро отдаёт процессор другим задачам, даже если программа не делает системных вызовов, и зависшая программа не захватит его навсегда. В режимах NO_HZ ядро подавляет лишние срабатывания таймера, когда это возможно.', 'Они позволяют ядру получать управление и вытеснять задачи без добровольного системного вызова. Обязательной периодичности на каждом CPU режимы NO_HZ не требуют: лишние срабатывания таймера подавляются.'),
        ('explanation', 'Программа получила через mmap новую анонимную область с правом записи, без MAP_POPULATE, и впервые записывает в одну из её страниц. Что верно?', NULL, NULL, 'Так работает выделение памяти по требованию, если страницы не подготовлены заранее (MAP_POPULATE, огромные страницы THP); malloc же может вернуть уже использованную память, а glibc сама пишет служебные данные в начало блока. Мелкие страничные ошибки обходятся без диска, крупные требуют чтения из файла или свопа. Счётчики процесса: ps -o pid,min_flt,maj_flt,cmd -p PID. Опыт 4 в examples/syscalls.c считает их при записи в 64 МБ.', 'Первая запись в неподготовленное анонимное отображение вызывает minor fault: ядро выделяет страницу. THP могут увеличить размер выделяемой страницы, но сами по себе не означают предварительного заполнения mmap; malloc же может вернуть уже использованную память, а glibc сама пишет служебные данные в начало блока. Мелкие страничные ошибки обходятся без диска, крупные требуют чтения из файла или свопа. Счётчики процесса: ps -o pid,min_flt,maj_flt,cmd -p PID. Опыт 4 в examples/syscalls.c считает их при записи в 64 МБ.'),
        ('option', 'Программа вызывает функции open() и fork(), а в выводе strace видны openat и clone. Почему?', 'Обёртки glibc open() и fork() вызывают openat и clone', 'Так open() и fork() реализованы в glibc', 'В современных glibc обёртки open() и fork() выполняют системные вызовы openat и clone (open так работает с glibc 2.26). Имена обёрток и вызовов ядра совпадают не всегда.', 'Обёртки libc не обязаны совпадать с одноимёнными вызовами ядра. В данном наблюдении open использует openat, а fork — clone; open так реализован в glibc начиная с 2.26.'),
        ('option', 'Что напечатает этот фрагмент в Linux x86-64 с glibc и локалью сообщений C?
```
ssize_t n = write(-1, "x", 1);
int saved = errno;
printf("%zd %s\n", n, strerror(saved));
```', '`0 Success`', '`-1 Permission denied`', 'Вызов не удался: записывать некуда.', 'Недопустимый дескриптор даёт EBADF, а не ошибку прав доступа.'),
        ('option', 'Что напечатает этот фрагмент в Linux x86-64 с glibc и локалью сообщений C?
```
ssize_t n = write(-1, "x", 1);
int saved = errno;
printf("%zd %s\n", n, strerror(saved));
```', '`1 Success`', '`-1 No such file or directory`', '1 вернулось бы, если бы байт был записан.', 'write не ищет файл по имени: здесь EBADF, а не ENOENT.'),
        ('option', 'Что напечатает этот фрагмент в Linux x86-64 с glibc и локалью сообщений C?
```
ssize_t n = write(-1, "x", 1);
int saved = errno;
printf("%zd %s\n", n, strerror(saved));
```', '`-9 Bad file descriptor`', NULL, 'Ядро действительно возвращает -9, но обёртка libc превращает это в -1 и записывает 9 в errno.', '-9 — сырой код ошибки Linux x86-64; обёртка write возвращает -1 и устанавливает errno.'),
        ('option', 'Что напечатает этот фрагмент в Linux x86-64 с glibc и локалью сообщений C?
```
ssize_t n = write(-1, "x", 1);
int saved = errno;
printf("%zd %s\n", n, strerror(saved));
```', '`-1 Bad file descriptor`', NULL, 'Файла с отрицательным номером не бывает: ядро возвращает ошибку EBADF.', 'write возвращает -1, errno = EBADF; в этой локали strerror выдаёт Bad file descriptor.'),
        ('option', 'Когда в программе на C имеет смысл читать errno после вызова write()?', 'После каждого вызова: значение 0 означает успех', 'После каждого write: при успехе errno равен нулю', 'Успешный вызов не обнуляет errno: там может остаться код старой ошибки.', 'Успешный write не обязан обнулять errno.'),
        ('option', 'Когда в программе на C имеет смысл читать errno после вызова write()?', 'Перед вызовом: errno подскажет, удастся ли запись', 'После успешного write, чтобы узнать число записанных байт', 'errno описывает уже случившуюся ошибку, а не предсказывает следующую.', 'Число записанных байт возвращает write, а не errno.'),
        ('option', 'Когда в программе на C имеет смысл читать errno после вызова write()?', 'В любой момент: errno хранит ошибки всех процессов', 'После printf: он сохраняет ошибку предыдущего write', 'errno своя у каждого потока каждого процесса.', 'Другие библиотечные вызовы могут изменить errno, поэтому его сохраняют сразу после ошибки.'),
        ('option', 'Когда в программе на C имеет смысл читать errno после вызова write()?', 'После того как write вернула -1, до других вызовов', 'После возврата -1 из write, до других вызовов', 'При -1 write сообщает причину в errno; следующие вызовы могут её перезаписать, поэтому код сохраняют сразу. После успешного write значение errno ничего не говорит об этой записи.', 'Возврат -1 означает ошибку; её код сохраняют до вызовов, которые могут изменить errno. После успешного write значение errno ничего не говорит об этой записи.'),
        ('option', 'Что не так в этом фрагменте?
```
write(fd, buf, len);
if (fdatasync(fd) == 0)
    printf("данные надёжно сохранены\n");
```', 'Результат write не проверен: запись могла быть неполной', 'Результат write не проверен перед вызовом fdatasync', 'Не проверен результат write: он мог записать меньше len байт или вернуть ошибку, а fdatasync сохранит только записанное. Успех fdatasync не исправляет ошибку предыдущей записи.', 'write мог вернуть ошибку или записать меньше len байт. Успешный fdatasync не дописывает отсутствующие данные и не исправляет ошибку write.'),
        ('explanation', 'Команда time показала: real 2.1s, user 0.4s, sys 1.6s. Что это значит?', NULL, NULL, 'На ядро пришлось 1.6 / (0.4 + 1.6) = 80 % процессорного времени; real 2.1 с — время по часам, его нельзя напрямую сравнивать с суммой user и sys. Сравните на любой машине: time dd if=/dev/zero of=/dev/null bs=1 count=1000000 и time dd if=/dev/zero of=/dev/null bs=1000000 count=1. Объём одинаковый, а sys различается на порядки.', 'На режим ядра пришлось 1.6 / (0.4 + 1.6) = 80 % процессорного времени. Сумму user и sys сравнивают с real, учитывая параллелизм и ожидания: суммарное процессорное время нескольких потоков или процессов может превышать real. Сравните на любой машине: time dd if=/dev/zero of=/dev/null bs=1 count=1000000 и time dd if=/dev/zero of=/dev/null bs=1000000 count=1. Объём одинаковый, а sys различается на порядки.'),
        ('explanation', 'Представление tiny построено на представлении small, а оно — на таблице t. Почему в выводе EXPLAIN SELECT * FROM tiny нет ни tiny, ни small, а есть только таблица t?', NULL, NULL, 'Условия обоих представлений попадут в план как объединённое условие на t. Проверка: EXPLAIN SELECT * FROM tiny; дерево после переписывания: SET client_min_messages = log; SET debug_print_rewritten = on; SELECT * FROM tiny; RESET debug_print_rewritten; RESET client_min_messages; (представления создаются в главе 2 материала).', 'При переписывании определения tiny и small раскрываются в подзапросы. В показанном случае планировщик упрощает их до доступа к t; условия простых представлений при этом могут объединяться. Проверка: EXPLAIN SELECT * FROM tiny; дерево после переписывания: SET client_min_messages = log; SET debug_print_rewritten = on; SELECT * FROM tiny; RESET debug_print_rewritten; RESET client_min_messages; (представления создаются в главе 2 материала).'),
        ('explanation', 'Допишите последнюю команду, чтобы получить фактический план DELETE и отменить его транзакционные изменения:
```
BEGIN;
EXPLAIN ANALYZE DELETE FROM t WHERE id <= 10;
___;
```', NULL, NULL, 'EXPLAIN ANALYZE выполняет любой запрос по-настоящему. Проверка после отката: SELECT count(*) FROM t; — число строк восстановится до исходного.', 'DELETE действительно выполняется; ROLLBACK отменяет его транзакционные изменения. Нетранзакционные побочные эффекты, например внешние действия триггера или nextval, таким откатом не отменяются. Проверка после отката: SELECT count(*) FROM t; — число строк восстановится до исходного.'),
        ('option', 'Чем команда ANALYZE t отличается от EXPLAIN ANALYZE SELECT * FROM t?', 'ANALYZE t и EXPLAIN ANALYZE собирают статистику, но вторая команда ещё показывает план', 'Обе команды обновляют статистику планировщика, а EXPLAIN ANALYZE ещё показывает план', 'ANALYZE t статистику собирает, а EXPLAIN ANALYZE нет: он выполняет запрос и показывает фактические цифры.', 'EXPLAIN ANALYZE собирает метрики выполнения, но не пересчитывает статистику столбцов для планировщика.'),
        ('option', 'Чем команда ANALYZE t отличается от EXPLAIN ANALYZE SELECT * FROM t?', 'ANALYZE t собирает статистику, а EXPLAIN ANALYZE выполняет запрос и заодно обновляет статистику', NULL, 'Статистику EXPLAIN ANALYZE не меняет: обновить её может только ANALYZE или автоочистка.', 'EXPLAIN ANALYZE не пересчитывает pg_statistic. Статистику столбцов собирает ANALYZE, в том числе запускаемый автоматически.'),
        ('option', 'Таблица уже проходила ANALYZE; оценка числа строк в pg_class.reltuples актуальна и положительна. При каком объёме изменений с последнего анализа она станет кандидатом на автоматический ANALYZE при настройках по умолчанию?', 'Когда с прошлого анализа изменится больше 50 строк + 10 % таблицы', NULL, 'Порог — 50 строк (autovacuum_analyze_threshold) плюс 10 % от оценки числа строк таблицы reltuples (autovacuum_analyze_scale_factor). После превышения порога таблица становится кандидатом: анализ выполнит автоочистка при обходе, когда есть свободный процесс-обработчик.', 'Порог — 50 строк (autovacuum_analyze_threshold) плюс 10 % от оценки числа строк reltuples (autovacuum_analyze_scale_factor). Если оценки ещё нет (reltuples = -1), берётся ноль и порог равен 50; в условии оценка есть. После превышения порога таблица становится кандидатом: анализ выполнит автоочистка при обходе, когда есть свободный процесс-обработчик.'),
        ('explanation', 'Что значит строка Heap Fetches: 999 в узле Index Only Scan?', NULL, NULL, 'Изменения строк снимают отметки в карте видимости, VACUUM ставит их снова. Опыт на копии v из главы 6 материала: UPDATE v SET val = val WHERE id < 1000; EXPLAIN (ANALYZE) SELECT id FROM v WHERE id < 1000; VACUUM v; и снова EXPLAIN.', 'Изменения снимают отметки all-visible. VACUUM может поставить их снова, когда оставшиеся версии строк страницы видны всем транзакциям; старые снимки могут этому помешать. Опыт на копии v из главы 6 материала: UPDATE v SET val = val WHERE id < 1000; EXPLAIN (ANALYZE) SELECT id FROM v WHERE id < 1000; VACUUM v; и снова EXPLAIN.'),
        ('option', 'У таблиц t и r одинаковые данные и индексы по id, но в t строки лежат по порядку id, а в r — в случайном порядке. После загрузки обеих таблиц выполнен ANALYZE, настройки планировщика одинаковы. Для условия id < 5000 в t выбран Index Scan, а в r — Bitmap Heap Scan. Почему?', 'В r корреляция около 0, и Index Scan оценён дороже из-за чтения вразброс', 'Низкая корреляция r повышает оценку цены Index Scan', 'В r корреляция около 0: Index Scan прыгал бы по страницам, и планировщик оценил его дороже. При низкой корреляции чтение страниц по индексу оценивается как произвольное, по random_page_cost.', 'При низкой корреляции Index Scan оценивается как более случайный доступ к страницам, а bitmap позволяет собрать обращения по страницам.'),
        ('option', 'У таблиц t и r одинаковые данные и индексы по id, но в t строки лежат по порядку id, а в r — в случайном порядке. После загрузки обеих таблиц выполнен ANALYZE, настройки планировщика одинаковы. Для условия id < 5000 в t выбран Index Scan, а в r — Bitmap Heap Scan. Почему?', 'Для таблицы, созданной копированием, планировщик по умолчанию выбирает Bitmap Heap Scan', 'Bitmap Heap Scan читает строки в порядке ключа id', 'Способ доступа не зависит от того, как таблица создана.', 'Bitmap Heap Scan обходит страницы таблицы в физическом порядке, а не в порядке ключей индекса.'),
        ('option', 'У таблиц t и r одинаковые данные и индексы по id, но в t строки лежат по порядку id, а в r — в случайном порядке. После загрузки обеих таблиц выполнен ANALYZE, настройки планировщика одинаковы. Для условия id < 5000 в t выбран Index Scan, а в r — Bitmap Heap Scan. Почему?', 'Индекс таблицы r повреждён, и планировщик его обходит', 'При Index Scan порядок строк таблицы не входит в оценку', 'Bitmap Heap Scan в плане r тоже использует индекс, так что индекс не обходится; по плану нельзя судить, исправен ли индекс физически.', 'Корреляция физического порядка строк с ключом учитывается в цене Index Scan.'),
        ('option', 'У таблиц t и r одинаковые данные и индексы по id, но в t строки лежат по порядку id, а в r — в случайном порядке. После загрузки обеих таблиц выполнен ANALYZE, настройки планировщика одинаковы. Для условия id < 5000 в t выбран Index Scan, а в r — Bitmap Heap Scan. Почему?', 'У таблицы r нет статистики, и оценки взяты по умолчанию', 'Bitmap Heap Scan получает строки без чтения таблицы', 'Статистика собрана: ANALYZE выполнен для обеих таблиц, и она как раз показывает разницу в корреляции.', 'Bitmap Heap Scan обращается к таблице за строками и проверкой видимости.'),
        ('option', 'Что верно для соединения Hash Join?', 'Если хеш-таблица не помещается в память, она делится на порции', 'Может разбивать данные на порции и использовать временные файлы', 'Лимит памяти — work_mem × hash_mem_multiplier.', 'Бюджет — work_mem × hash_mem_multiplier. Обычно используются порции и временные файлы; при неудачном разбиении рост числа порций может остановиться, а расход превысить бюджет.'),
        ('option', 'Сортировка 100 000 строк по val в памяти (одинаковые данные и work_mem, в обоих планах Sort Method: quicksort) заняла 264 мс с COLLATE "C" и 2049 мс с COLLATE "ru_RU.utf8". Почему такая разница?', 'С правилами ru_RU.utf8 строки сортируются на диске', 'Сравнение ru_RU выполняется через интерпретатор SQL', 'В обоих случаях сортировка шла в памяти: quicksort.', 'Сравнение выполняет библиотека коллации, а не интерпретатор SQL.'),
        ('option', 'Сортировка 100 000 строк по val в памяти (одинаковые данные и work_mem, в обоих планах Sort Method: quicksort) заняла 264 мс с COLLATE "C" и 2049 мс с COLLATE "ru_RU.utf8". Почему такая разница?', 'Для правил ru_RU.utf8 сортировке понадобилось заметно больше work_mem', 'Коллация ru_RU отключает кеширование страниц таблицы', 'По условию work_mem одинаков и обе сортировки поместились в память; наблюдаемую разницу объясняет стоимость сравнений.', 'Выбор коллации не отключает буферный кеш и кеш ОС.'),
        ('option', 'Сортировка 100 000 строк по val в памяти (одинаковые данные и work_mem, в обоих планах Sort Method: quicksort) заняла 264 мс с COLLATE "C" и 2049 мс с COLLATE "ru_RU.utf8". Почему такая разница?', 'Сравнение по правилам языка намного дороже побайтового сравнения в C', 'Сравнение ru_RU дороже побайтового сравнения C', 'Сравнение по правилам языка многоуровневое и намного дороже побайтового сравнения в C. При сотнях тысяч сравнений разница в цене одного сравнения становится главной.', 'Языковые правила требуют более сложной обработки строк, чем побайтовое сравнение C; при сотнях тысяч сравнений разница в цене одного сравнения становится главной.'),
        ('option', 'Сортировка 100 000 строк по val в памяти (одинаковые данные и work_mem, в обоих планах Sort Method: quicksort) заняла 264 мс с COLLATE "C" и 2049 мс с COLLATE "ru_RU.utf8". Почему такая разница?', 'С COLLATE "C" вместо сортировки используется индекс по val', 'Планировщик добавляет SQL-нормализацию строк для ru_RU', 'По условию выполнялась сортировка; замена её индексным доступом не показана.', 'Планировщик не добавляет такую SQL-нормализацию; меняется функция сравнения сортировки.')
    ) AS fixes(kind, question_text, opt_text, new_opt_text, old_text, new_text)
    LOOP
        -- Сначала ровно один вопрос по тексту (прежнему или новому), дальше всё только по его id.
        SELECT count(*), min(id) INTO matches, qid FROM questions
        WHERE question_text IN (fix.question_text, CASE WHEN fix.kind = 'question' THEN fix.new_text ELSE fix.question_text END);
        IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вопрос для исправления'; END IF;
        IF fix.kind = 'question' THEN
            UPDATE questions SET question_text = fix.new_text WHERE id = qid;
        ELSIF fix.kind = 'explanation' THEN
            PERFORM 1 FROM questions WHERE id = qid AND explanation IN (fix.old_text, fix.new_text);
            IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение вопроса'; END IF;
            UPDATE questions SET explanation = fix.new_text WHERE id = qid;
        ELSE
            SELECT count(*), min(o.key) INTO matches, k
            FROM questions q, jsonb_each_text(q.options) o
            WHERE q.id = qid AND o.value IN (fix.opt_text, coalesce(fix.new_opt_text, fix.opt_text));
            IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вариант ответа для исправления'; END IF;
            IF fix.new_text IS NOT NULL THEN
                PERFORM 1 FROM questions WHERE id = qid AND option_notes ->> k IN (fix.old_text, fix.new_text);
                IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение варианта'; END IF;
                UPDATE questions SET option_notes = jsonb_set(option_notes, ARRAY[k], to_jsonb(fix.new_text)) WHERE id = qid;
            END IF;
            IF fix.new_opt_text IS NOT NULL THEN
                UPDATE questions SET options = jsonb_set(options, ARRAY[k], to_jsonb(fix.new_opt_text)) WHERE id = qid;
            END IF;
        END IF;
    END LOOP;
END
$fix$;

COMMIT;
